const $=s=>document.querySelector(s);let category=categories[0],view='all',current;let favorites=[],recent=[];try{favorites=JSON.parse(localStorage.getItem('toolhub-favorites')||'[]');recent=JSON.parse(localStorage.getItem('toolhub-recent')||'[]')}catch{}const save=()=>{try{localStorage.setItem('toolhub-favorites',JSON.stringify(favorites));localStorage.setItem('toolhub-recent',JSON.stringify(recent))}catch{}};
function renderNav(){ $('#nav').innerHTML=categories.map((c,i)=>`<button data-cat="${c}" class="${category===c&&view==='all'?'active':''}"><i>${['▦','⌘','Tt','♧','◈','◎','↔','◷','⌁'][i]}</i>${c}${!i?`<span class="num">${tools.length}</span>`:''}</button>`).join('')+`<div class="nav-divider"></div><button data-view="favorites" class="${view==='favorites'?'active':''}"><i>☆</i>Yêu thích<span class="num">${favorites.length}</span></button><button data-view="recent" class="${view==='recent'?'active':''}"><i>◷</i>Đã dùng gần đây</button>`;$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{view=b.dataset.view||'all';category=b.dataset.cat||categories[0];render()})}
function render(){renderNav();$('#filters').innerHTML=categories.map(c=>`<button class="${category===c?'active':''}" data-filter="${c}">${c}</button>`).join('');$('#filters').querySelectorAll('button').forEach(b=>b.onclick=()=>{category=b.dataset.filter;view='all';render()});let query=$('#search').value.toLocaleLowerCase('vi');let list=tools.filter(t=>(category===categories[0]||t.cat===category)&&(view==='all'||(view==='favorites'?favorites:recent).includes(t.id))&&(t.name+' '+t.desc+' '+t.cat).toLocaleLowerCase('vi').includes(query));if(view==='recent')list.sort((a,b)=>recent.indexOf(a.id)-recent.indexOf(b.id));let title=view==='favorites'?'Công cụ yêu thích':view==='recent'?'Đã dùng gần đây':category;$('#crumb').textContent=title;$('#sectionTitle').textContent=title+' ';let count=document.createElement('span');count.textContent=list.length;$('#sectionTitle').append(count);$('#grid').innerHTML=list.map(t=>`<article class="card" style="--tone:${t.tone};--tint:${t.tint}"><button class="favorite ${favorites.includes(t.id)?'selected':''}" aria-label="${favorites.includes(t.id)?'Bỏ':'Thêm'} yêu thích ${t.name}" data-fav="${t.id}">${favorites.includes(t.id)?'★':'☆'}</button><button class="card-main" data-open="${t.id}"><span class="icon">${t.icon}</span><h3>${t.name}</h3><p>${t.desc}</p><div class="card-bottom"><span>${t.cat.toLocaleUpperCase('vi')}</span><span>Mở công cụ →</span></div></button></article>`).join('');$('#empty').hidden=!!list.length;$('#emptyMessage').textContent=view==='favorites'&&!query?'Chưa có công cụ yêu thích. Nhấn ngôi sao trên công cụ bạn thường dùng.':view==='recent'&&!query?'Các công cụ bạn mở sẽ xuất hiện tại đây.':'Không tìm thấy công cụ. Hãy thử từ khóa khác.';$('#grid').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openTool(b.dataset.open));$('#grid').querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{let id=b.dataset.fav;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save();render()})}
const textInput='<label for="input">Nội dung đầu vào</label><textarea id="input" placeholder="Dán hoặc nhập nội dung tại đây…"></textarea>';const field=(id,label,value,type='text')=>`<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${value}">`;
function prepareTool(id){current=tools.find(t=>t.id===id);recent=[id,...recent.filter(x=>x!==id)].slice(0,12);save();$('#toolTitle').textContent=current.name;$('#toolCategory').textContent=current.cat;$('#toolDesc').textContent=current.desc;$('#output').value='';$('#status').textContent='';let actions=[];$('#fields').innerHTML=ToolHubAdvanced.ids.includes(id)?'':['fakejson','jwt','meta','campaign','hash'].includes(id)?devFields(id):id==='stopwatch'?'':id==='random'?randomFields():id==='currency'?currencyFields():id==='signature'?signatureFields():id==='ip'?ipFields():id==='password'?passwordFields():id==='radix'?textInput+field('fromBase','Hệ số đầu vào (2–36)',10,'number')+field('toBase','Hệ số kết quả (2–36)',16,'number'):id==='lorem'?field('paragraphs','Số đoạn văn (1–30)',3,'number')+'<label for="language">Ngôn ngữ</label><select id="language"><option value="vi">Tiếng Việt</option><option value="latin">Lorem ipsum</option></select>':id==='uuid'?field('amount','Số lượng UUID (1–100)',5,'number'):id==='color'?field('input','Mã màu HEX','#236b52'):id==='timestamp'?field('input','Unix timestamp (giây) hoặc ngày giờ ISO',Math.floor(Date.now()/1000)):id==='percent'?field('part','Giá trị phần',25,'number')+field('total','Giá trị tổng',200,'number'):textInput;
if(id==='json')actions=[['Định dạng',()=>JSON.stringify(JSON.parse(val()),null,2)],['Thu gọn',()=>JSON.stringify(JSON.parse(val()))]];
if(id==='base64')actions=[['Mã hóa',()=>btoa(Array.from(new TextEncoder().encode(val()),x=>String.fromCharCode(x)).join(''))],['Giải mã',()=>new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(val().trim()),c=>c.charCodeAt(0)))]];
if(id==='url')actions=[['Mã hóa',()=>encodeURIComponent(val())],['Giải mã',()=>decodeURIComponent(val())]];
if(id==='uuid')actions=[['Tạo UUID',()=>Array.from({length:bounded('amount',1,100)},()=>crypto.randomUUID()).join('\n')]];
if(id==='password')actions=[['Tạo mật khẩu',()=>ToolHubLogic.passwords(readPasswordOptions())]];
if(id==='words')actions=[['Đếm văn bản',()=>{let s=val(),n=s.trim()?s.trim().split(/\s+/u).length:0;return `${n} từ\n${Array.from(s).length} ký tự (có khoảng trắng)\n${Array.from(s.replace(/\s/gu,'')).length} ký tự (không có khoảng trắng)\n${s?s.split(/\n/).length:0} dòng\nThời gian đọc: ${n?Math.ceil(n/200):0} phút (ước tính)`}]];
if(id==='case')actions=[['CHỮ HOA',()=>val().toLocaleUpperCase('vi')],['chữ thường',()=>val().toLocaleLowerCase('vi')],['Viết Hoa Đầu Từ',()=>val().toLocaleLowerCase('vi').replace(/(^|\s)(\p{L})/gu,(_,s,c)=>s+c.toLocaleUpperCase('vi'))]];
if(id==='slug')actions=[['Tạo slug',()=>val().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')]];
if(id==='lines')actions=[['Xóa dòng trùng',()=>[...new Set(val().split('\n'))].join('\n')],['Sắp xếp A–Z',()=>val().split('\n').sort((a,b)=>a.localeCompare(b,'vi')).join('\n')],['Bỏ dòng trống',()=>val().split('\n').filter(s=>s.trim()).join('\n')]];
if(id==='percent')actions=[['Tính phần trăm',()=>{let a=Number($('#part').value),b=Number($('#total').value);if(!$('#part').value||!$('#total').value||!Number.isFinite(a)||!Number.isFinite(b)||b===0)throw Error('Nhập hai số hợp lệ; giá trị tổng phải khác 0.');return `${a} / ${b} × 100 = ${Number((a/b*100).toFixed(6))}%`}]];
if(id==='timestamp')actions=[['Chuyển đổi',()=>{let v=val().trim(),d=/^-?\d+$/.test(v)?new Date(Number(v)*1000):new Date(v);if(isNaN(d.getTime()))throw Error('Nhập timestamp theo giây hoặc ngày ISO, ví dụ 2026-10-19T09:00:00+07:00.');return `Unix (giây): ${Math.floor(d.getTime()/1000)}\nISO: ${d.toISOString()}\nĐịa phương: ${d.toLocaleString('vi-VN')}\nMúi giờ: ${Intl.DateTimeFormat().resolvedOptions().timeZone}`}]];
if(id==='color')actions=[['Chuyển đổi màu',()=>{let hex=val().trim().replace(/^#/,'');if(!/^(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(hex))throw Error('Nhập mã HEX gồm 3 hoặc 6 ký tự, ví dụ #236b52.');if(hex.length===3)hex=[...hex].map(c=>c+c).join('');let rgb=[0,2,4].map(i=>parseInt(hex.slice(i,i+2),16)),[r,g,b]=rgb.map(v=>v/255),max=Math.max(r,g,b),min=Math.min(r,g,b),l=(max+min)/2,d=max-min,h=0,s=0;if(d){s=d/(1-Math.abs(2*l-1));h=(max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4)*60}return `HEX: #${hex.toUpperCase()}\nRGB: rgb(${rgb.join(', ')})\nHSL: hsl(${Math.round(h)}, ${Math.round(s*100)}%, ${Math.round(l*100)}%)`}]];
if(id==='random')actions=[['Tạo số ngẫu nhiên',()=>ToolHubRandomTime.numbers(readRandom())]];
if(id==='currency')actions=[['Quy đổi',()=>convertCurrency(false)],['Cập nhật tỷ giá',()=>convertCurrency(true)]];
if(id==='signature')actions=[['Cập nhật chữ ký',()=>ToolHubSignature.build(readSignature())]];
if(id==='ip')actions=[['Xem IP của tôi',()=>lookupIp('')],['Tra cứu IP đã nhập',()=>lookupIp(val())]];
if(id==='hash')actions=[['Tạo mã băm',()=>ToolHubDev.hashText(readHash())]];
if(id==='fakejson')actions=[['Tạo dữ liệu JSON',()=>ToolHubDev.fake($('#fakeSchema').value,$('#fakeCount').value)]];
if(id==='jwt')actions=[['Giải mã JWT',()=>ToolHubDev.debugJwt(val(),'',false)],['Xác minh HMAC',()=>ToolHubDev.debugJwt(val(),$('#jwtSecret').value,true)]];
if(id==='meta')actions=[['Tạo Meta Tag',()=>ToolHubDev.meta(readMeta())]];
if(id==='campaign')actions=[['Tạo URL chiến dịch',()=>ToolHubDev.campaign(readCampaign())]];
if(id==='html')actions=[['Mã hóa HTML',()=>ToolHubLogic.htmlEncode(val())],['Giải mã HTML',()=>{const parser=new DOMParser();return parser.parseFromString('<body>'+val().replace(/</g,'&lt;').replace(/>/g,'&gt;'),'text/html').body.textContent}]];
if(id==='radix')actions=[['Chuyển hệ số',()=>ToolHubLogic.convertBase(val(),$('#fromBase').value,$('#toBase').value)]];
if(id==='query')actions=[['Xem danh sách',()=>{const params=readQuery();return [...params].map(([k,v])=>k+' = '+v).join('\n')||'Không có tham số.'}],['Xuất JSON',()=>{const result=Object.create(null);for(const [key,value] of readQuery()){if(Object.hasOwn(result,key))result[key]=Array.isArray(result[key])?[...result[key],value]:[result[key],value];else result[key]=value;}return JSON.stringify(result,null,2)}]];
if(id==='lorem')actions=[['Tạo văn bản mẫu',()=>{const n=ToolHubLogic.integer($('#paragraphs').value,1,30,'Số đoạn');const paragraphs=$('#language').value==='vi'?['Mỗi ý tưởng bắt đầu từ một câu hỏi nhỏ. Khi dành thời gian quan sát và thử nghiệm, chúng ta tìm thấy những cách làm đơn giản hơn cho công việc mỗi ngày.','Một giao diện rõ ràng giúp người dùng tập trung vào điều cần làm. Nội dung, khoảng cách và màu sắc cùng tạo nên trải nghiệm dễ hiểu và thuận tiện.','Đây là văn bản mẫu để kiểm tra bố cục, kiểu chữ và khoảng cách giữa các đoạn. Bạn có thể thay thế nội dung này bằng câu chuyện của riêng mình.']:['Lorem ipsum dolor sit amet, consectetur adipiscing elit. Integer vitae libero at velit interdum facilisis. Donec tincidunt, justo ut aliquet volutpat, augue sapien tristique erat.','Praesent commodo cursus magna, vel scelerisque nisl consectetur et. Aenean lacinia bibendum nulla sed consectetur. Etiam porta sem malesuada magna mollis euismod.'];return Array.from({length:n},(_,i)=>paragraphs[i%paragraphs.length]).join('\n\n')}]];
if(id==='emails')actions=[['Trích xuất email',()=>ToolHubLogic.extractEmails(val())]];
$('#actions').innerHTML='';actions.forEach(([label,fn])=>{let b=document.createElement('button');b.textContent=label;b.onclick=async()=>{const revision=++resultRevision;if(id==='ip'||id==='currency'){$('#status').textContent=id==='ip'?'Đang tra cứu IP…':'Đang lấy tỷ giá…';$('#status').style.color='';$('#status').dataset.error='false';$('#ipResult').hidden=true;if(id==='currency')$('#currencyResult').hidden=true;$('#output').value='';$('#output').setAttribute('aria-busy','true');syncResult()}try{const result=await fn();if(revision!==resultRevision||current.id!==id)return;if(['fakejson','jwt','meta','campaign','hash'].includes(id)){renderDev(result);$('#output').value=result.text}else if(id==='random'){renderRandom(result);$('#output').value=result.values.join('\n')}else if(id==='currency'){renderCurrency(result);$('#output').value=result.text}else if(id==='signature'){renderSignature(result);$('#output').value=result.html}else if(id==='ip'){renderIpResult(result);$('#output').value=result.text}else $('#output').value=result;$('#status').textContent=id==='currency'?'Đã quy đổi tiền tệ.':id==='ip'?'Đã xử lý thông tin IP.':'Đã xử lý trên trình duyệt.';$('#status').style.color='';$('#status').dataset.error='false'}catch(e){if(revision!==resultRevision||current.id!==id)return;if(['fakejson','jwt','meta','campaign','hash'].includes(id)){$('#devResult').hidden=true;lastDev=null;}if(id==='random'){$('#randomResult').hidden=true;lastRandom=null;}if(id==='currency'){$('#currencyResult').hidden=true;lastCurrency=null;}if(id==='signature'){$('#signatureResult').hidden=true;lastSignature=null;}$('#output').value='';$('#status').textContent=id==='json'?'JSON chưa hợp lệ. Kiểm tra dấu ngoặc, dấu phẩy và dấu nháy kép.':id==='base64'?'Nội dung Base64 hoặc UTF-8 chưa hợp lệ.':id==='url'?'Chuỗi URL chưa hợp lệ. Kiểm tra các ký tự mã hóa %.':e.message;$('#status').style.color='#b14e3e';$('#status').dataset.error='true'}$('#output').setAttribute('aria-busy','false');syncResult();rememberDraft();};$('#actions').append(b)});if(!$('#dialog').open)$('#dialog').showModal();render();}
function val(){return $('#input').value}function bounded(id,min,max){let n=Number($('#'+id).value);if(!Number.isInteger(n)||n<min||n>max)throw Error(`Nhập số nguyên từ ${min} đến ${max}.`);return n}
$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){let r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close()}});$('#copy').onclick=async()=>{if(!$('#output').value)return;try{await navigator.clipboard.writeText($('#output').value);$('#status').textContent='Đã sao chép kết quả.'}catch{$('#output').select();$('#status').textContent='Nhấn Ctrl+C hoặc ⌘C để sao chép.'}};$('#search').oninput=render;document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('#search').value=b.dataset.query;render()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();$('#search').focus()}});$('#share').href='mailto:?subject=ToolHub&body='+encodeURIComponent('Bộ công cụ cho công việc mỗi ngày: '+location.href);render();

