const drafts=new Map();let activeAction=0,autoTimer,resultRevision=0,ipRequest,lastIpData=null,lastSignature=null,lastCurrency=null,lastRandom=null,lastDev=null;
const examples={json:'{"project":"ToolHub","language":"Tiếng Việt","tools":["JSON","Base64"],"ready":true}',base64:'Xin chào Việt Nam!',url:'https://example.com/tìm kiếm?q=công cụ',words:'ToolHub giúp bạn xử lý những công việc nhỏ mỗi ngày.\nDán nội dung và xem thống kê tại đây.',case:'xin chào, đây là ToolHub',slug:'10 công cụ hữu ích dành cho lập trình viên',color:'#236b52',timestamp:'2026-10-19T09:00:00+07:00',hash:'Xin chào Việt Nam!',html:'<button title="Chào bạn">Lưu & tiếp tục</button>',radix:'255',query:'https://example.com/search?q=công+cụ&tag=dev&tag=design',emails:'Liên hệ: dev@example.com, DESIGN@example.org. Gửi lại cho dev@example.com.',lines:'Thiết kế\nLập trình\nThiết kế\n\nViết nội dung'};
function rememberDraft(){if(!current)return;drafts.set(current.id,{fields:[...$('#fields').querySelectorAll('input,textarea,select')].filter(el=>!['jwtSecret','hashSecret'].includes(el.id)).map(el=>[el.id,el.type==='checkbox'?el.checked:el.value]),output:$('#output').value,status:$('#status').textContent,error:$('#status').dataset.error==='true',action:activeAction,auto:$('#autoRun').checked,dev:['fakejson','jwt','meta','campaign','hash'].includes(current.id)&&$('#output').value?lastDev:null,random:current.id==='random'&&$('#output').value?lastRandom:null,currency:current.id==='currency'&&$('#output').value?lastCurrency:null,signature:current.id==='signature'&&$('#output').value?lastSignature:null,ipData:current.id==='ip'&&$('#output').value?lastIpData:null});}
function syncResult(){const value=$('#output').value;const isSignature=current?.id==='signature';const canReuse=!isSignature&&!['fakejson','jwt','meta'].includes(current?.id)&&!!$('#fields textarea');if($('#sigJump'))$('#sigJump').disabled=!value;$('#copy').textContent=isSignature?'Sao chép HTML':'Sao chép kết quả';$('#download').textContent=isSignature||current?.id==='meta'?'Tải .html ↓':['fakejson','jwt'].includes(current?.id)?'Tải .json ↓':'Tải .txt ↓';document.querySelector('.output-label').textContent=isSignature?'Xem trước & HTML':'Kết quả';$('#reuse').hidden=!canReuse;['copy','download','showResult'].forEach(id=>$('#'+id).disabled=!value);$('#reuse').disabled=!value||!canReuse;$('#reuse').hidden=!canReuse;$('#resultMeta').textContent=value?`${Array.from(value).length.toLocaleString('vi-VN')} ký tự · ${value.split('\n').length} dòng`:'Chưa có kết quả';$('#fields').querySelectorAll('input,textarea,select').forEach(el=>el.setAttribute('aria-invalid',$('#status').dataset.error==='true'?'true':'false'));}
function chooseAction(index){activeAction=index;$('#actions').querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('chosen',i===index);b.setAttribute('aria-pressed',String(i===index))});}
function runAction(){const button=$('#actions').children[activeAction];if(button)button.click();}
function openTool(id){ToolHubAdvanced.leave();$('#advancedWorkspace').hidden=true;cancelAnimationFrame(stopwatchFrame);currencyRequest?.abort();ipRequest?.abort();++resultRevision;clearTimeout(autoTimer);rememberDraft();const draft=drafts.get(id);prepareTool(id);if(ToolHubAdvanced.ids.includes(id)){$('#toolSelect').value=id;document.querySelector('.workbench-grid').hidden=true;$('#stopwatchWorkspace').hidden=true;document.querySelector('.draft-note').hidden=true;document.querySelector('.workbench-private').textContent='● Xử lý trên thiết bị';ToolHubAdvanced.open(id);$('#dialog').scrollTop=0;return}const pane=document.querySelector('.input-pane'),area=document.querySelector('.action-area');if(id==='password')pane.insertBefore(area,$('#fields'));else pane.append(area);pane.querySelector('h3').textContent=id==='password'?'Tùy chọn tạo mật khẩu':'Đầu vào';$('#toolSelect').value=id;$('#status').dataset.error='false';$('#status').style.color='';activeAction=draft?.action||0;const random=['uuid','password','lorem','ip','currency','random','stopwatch','fakejson'].includes(id);$('#autoRun').closest('label').hidden=random;$('#autoRun').checked=draft?.auto??['words','slug','color','percent','signature'].includes(id);$('#example').hidden=random&&id!=='ip';$('#clear').hidden=random;
const numeric=$('#amount');if(numeric){numeric.min=1;numeric.max=100;numeric.step=1;}
$('#fields').querySelectorAll('input,textarea,select').forEach(el=>{el.setAttribute('aria-describedby','status');el.spellcheck=false;el.addEventListener('input',()=>{++resultRevision;clearTimeout(autoTimer);$('#output').value='';$('#status').textContent='';$('#status').dataset.error='false';if(['fakejson','jwt','meta','campaign','hash'].includes(current.id)){$('#devResult').hidden=true;lastDev=null;}if(current.id==='random'){$('#randomResult').hidden=true;lastRandom=null;}if(current.id==='currency'){$('#currencyResult').hidden=true;lastCurrency=null;currencyRequest?.abort();$('#output').setAttribute('aria-busy','false');}if(current.id==='signature'){$('#signatureResult').hidden=true;lastSignature=null;}syncResult();rememberDraft();if(current.id==='ip'){$('#output').setAttribute('aria-busy','false');$('#ipResult').hidden=true;lastIpData=null;ipRequest?.abort()}if(current.id==='password')updatePasswordSummary();if($('#autoRun').checked)autoTimer=setTimeout(()=>{if(current.id==='signature'||el.value.trim())runAction()},300)});el.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();clearTimeout(autoTimer);runAction()}})});
$('#actions').querySelectorAll('button').forEach((button,i)=>{const handler=button.onclick;button.onclick=()=>{clearTimeout(autoTimer);chooseAction(i);handler()}});chooseAction(activeAction);
if(draft){draft.fields.forEach(([key,value])=>{const el=$('#'+key);if(el){if(el.type==='checkbox')el.checked=value;else el.value=value}});$('#output').value=draft.output;$('#status').textContent=draft.status;$('#status').dataset.error=String(draft.error);$('#status').style.color=draft.error?'#b14e3e':'';}syncResult();if(id==='password')setupPasswordControls();$('#signatureResult').hidden=id!=='signature'||!draft?.signature;if(id==='signature'&&draft?.signature)renderSignature(draft.signature);
$('#devResult').hidden=!['fakejson','jwt','meta','campaign','hash'].includes(id)||!draft?.dev;if(['fakejson','jwt','meta','campaign','hash'].includes(id)){setupDev(id);if(draft?.dev)renderDev(draft.dev);}$('#randomResult').hidden=id!=='random'||!draft?.random;if(id==='random'&&draft?.random)renderRandom(draft.random);$('#stopwatchWorkspace').hidden=id!=='stopwatch';document.querySelector('.workbench-grid').hidden=id==='stopwatch';document.querySelector('.draft-note').hidden=id==='stopwatch';if(id==='stopwatch')setupStopwatch();document.querySelector('.workbench-private').textContent=['ip','currency'].includes(id)?'◎ Tra cứu trực tuyến':'● Xử lý trên trình duyệt';$('#currencyResult').hidden=id!=='currency'||!draft?.currency;if(id==='currency'){setupCurrency();if(draft?.currency)renderCurrency(draft.currency);}$('#output').setAttribute('aria-busy','false');$('#ipResult').hidden=id!=='ip'||!draft?.ipData;if(id==='ip'&&draft?.ipData)renderIpResult(draft.ipData);
if(!draft&&((random&&!['ip','currency','stopwatch'].includes(id))||['percent','color','timestamp','signature','meta','campaign'].includes(id)))runAction();$('#dialog').scrollTop=0;$('#fields').querySelector('textarea,input')?.focus({preventScroll:true});}
$('#toolSelect').innerHTML=categories.slice(1).map(category=>`<optgroup label="${category}">${tools.filter(t=>t.cat===category).map(t=>`<option value="${t.id}">${t.name}</option>`).join('')}</optgroup>`).join('');$('#toolSelect').onchange=e=>openTool(e.target.value);
$('#example').onclick=async()=>{clearTimeout(autoTimer);if(['jwt','meta','campaign','hash'].includes(current.id)){await fillDevExample(current.id);chooseAction(0);runAction();return}if(current.id==='signature'){fillSignatureExample();chooseAction(0);runAction();return}if(current.id==='ip')$('#input').value='8.8.8.8';else if(current.id==='radix'){$('#input').value='255';$('#fromBase').value=10;$('#toBase').value=16}else if(current.id==='percent'){$('#part').value=25;$('#total').value=200}else $('#input').value=examples[current.id]||'';chooseAction(current.id==='ip'?1:0);runAction();$('#fields').querySelector('textarea,input')?.focus({preventScroll:true})};
$('#clear').onclick=()=>{if(['fakejson','jwt','meta','campaign','hash'].includes(current.id)){$('#devResult').hidden=true;lastDev=null;}if(current.id==='signature'){clearSignature();return}++resultRevision;clearTimeout(autoTimer);$('#fields').querySelectorAll('input,textarea,select').forEach(el=>el.value='');if(current.id==='hash'){$('#hashAlgorithm').value='SHA-256';$('#hashEncoding').value='hex';$('#hashHmac').checked=false;$('#hashSecret').disabled=true;}$('#output').value='';$('#status').textContent='';$('#status').dataset.error='false';syncResult();rememberDraft();$('#fields').querySelector('textarea,input')?.focus({preventScroll:true})};
$('#autoRun').onchange=()=>{rememberDraft();clearTimeout(autoTimer);if($('#autoRun').checked&&$('#fields').querySelector('input,textarea')?.value.trim())runAction()};
$('#reuse').onclick=()=>{clearTimeout(autoTimer);const input=$('#fields textarea');if(!input)return;input.value=$('#output').value;$('#output').value='';$('#status').textContent='Đã chuyển kết quả sang đầu vào. Chọn thao tác tiếp theo.';$('#status').dataset.error='false';$('#status').style.color='';syncResult();rememberDraft();input.focus({preventScroll:true})};
$('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([$('#output').value],{type:['signature','meta'].includes(current.id)?'text/html;charset=utf-8':['fakejson','jwt'].includes(current.id)?'application/json;charset=utf-8':'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`toolhub-${current.id}.${current.id==='signature'||current.id==='meta'?'html':current.id==='fakejson'||current.id==='jwt'?'json':'txt'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#dialog').addEventListener('close',()=>{ToolHubAdvanced.leave();cancelAnimationFrame(stopwatchFrame);++resultRevision;clearTimeout(autoTimer);rememberDraft();document.querySelector(`[data-open="${current?.id}"]`)?.focus({preventScroll:true})});
$('#resetFilters').onclick=()=>{$('#search').value='';category=categories[0];view='all';render();$('#search').focus()};

