function checkbox(id,label,checked=true){return `<label class="option-row" for="${id}"><input type="checkbox" id="${id}" ${checked?'checked':''}><span>${label}</span></label>`}
function passwordFields(){return `<div class="password-presets" aria-label="Cấu hình nhanh"><span>Cấu hình nhanh</span><div><button data-preset="strong">Đầy đủ ký tự · 20</button><button data-preset="readable">Dễ đọc · 16</button><button data-preset="pin">PIN · 6 số</button></div></div><div class="number-options">${field('pwdLength','Độ dài (4–128 ký tự)',20,'number')}${field('pwdCount','Số mật khẩu (1–50)',1,'number')}</div><fieldset class="password-group"><legend>Nhóm ký tự</legend>${checkbox('pwdUpper','Chữ hoa (A–Z)')}${checkbox('pwdLower','Chữ thường (a–z)')}${checkbox('pwdDigits','Chữ số (0–9)')}${checkbox('pwdSymbols','Ký hiệu đặc biệt')}${field('pwdCustomSymbols','Ký hiệu được phép',ToolHubLogic.symbols)}</fieldset><fieldset class="password-group"><legend>Tùy chọn bổ sung</legend>${checkbox('pwdAmbiguous','Bỏ ký tự dễ nhầm: I, l, 1, O, 0, o và dấu nháy')}${checkbox('pwdEvery','Có ít nhất một ký tự từ mỗi nhóm đã chọn')}${checkbox('pwdUnique','Không lặp ký tự trong từng mật khẩu',false)}${field('pwdExclude','Loại thêm các ký tự này (tùy chọn)','')}</fieldset><p class="password-summary" id="passwordSummary" role="status"></p><p class="password-note">Tạo ngẫu nhiên bằng bộ sinh mật mã của trình duyệt. Mỗi mật khẩu nằm trên một dòng.</p>`}
function readPasswordOptions(){return {length:$('#pwdLength').value,count:$('#pwdCount').value,upper:$('#pwdUpper').checked,lower:$('#pwdLower').checked,digits:$('#pwdDigits').checked,symbols:$('#pwdSymbols').checked,customSymbols:$('#pwdCustomSymbols').value,ambiguous:$('#pwdAmbiguous').checked,everyGroup:$('#pwdEvery').checked,unique:$('#pwdUnique').checked,exclude:$('#pwdExclude').value}}
function updatePasswordSummary(){if(current?.id!=='password')return;$('#pwdCustomSymbols').disabled=!$('#pwdSymbols').checked;try{const c=ToolHubLogic.passwordConfig(readPasswordOptions());$('#passwordSummary').textContent=`${c.count} mật khẩu × ${c.length} ký tự · Bộ ${c.pool.length} ký tự được phép`;$('#passwordSummary').classList.remove('invalid')}catch(e){$('#passwordSummary').textContent=e.message;$('#passwordSummary').classList.add('invalid')}}
function setupPasswordControls(){for(const [id,min,max] of [['pwdLength',4,128],['pwdCount',1,50]]){const el=$('#'+id);el.min=min;el.max=max;el.step=1}$('#pwdCustomSymbols').maxLength=94;$('#pwdExclude').maxLength=128;$('#fields').querySelectorAll('[data-preset]').forEach(button=>button.onclick=()=>{++resultRevision;const preset=button.dataset.preset;$('#pwdLength').value=preset==='pin'?6:preset==='readable'?16:20;for(const id of ['pwdUpper','pwdLower','pwdDigits','pwdSymbols'])$('#'+id).checked=preset==='pin'?id==='pwdDigits':preset==='readable'?id!=='pwdSymbols':true;$('#pwdCustomSymbols').value=ToolHubLogic.symbols;$('#pwdAmbiguous').checked=preset!=='pin';$('#pwdEvery').checked=true;$('#pwdUnique').checked=false;$('#pwdExclude').value='';updatePasswordSummary();rememberDraft();runAction()});updatePasswordSummary()}
function readQuery(){let s=val().trim();if(!s)throw Error('Nhập URL đầy đủ hoặc chuỗi tham số, ví dụ ?q=toolhub&lang=vi.');if(/^[a-z][a-z0-9+.-]*:\/\//i.test(s)){let url;try{url=new URL(s)}catch{throw Error('URL chưa hợp lệ. Hãy dùng URL đầy đủ hoặc chuỗi ?key=value.')}return url.searchParams}if(s.startsWith('?'))s=s.slice(1);return new URLSearchParams(s.split('#')[0])}

function ipFields(){return field('input','Địa chỉ IP cần tra cứu (IPv4 hoặc IPv6)','','text')+'<p class="ip-hint">Để xem IP đang dùng, nhấn “Xem IP của tôi”. Hoặc nhập IP khác rồi chọn “Tra cứu IP đã nhập”.</p><div class="ip-notice"><strong>Tra cứu trực tuyến qua IP.SB</strong><p>Khi bạn nhấn tra cứu, dịch vụ nhận IP kết nối và địa chỉ IP cần tìm. ToolHub không lưu lịch sử địa chỉ IP.</p></div><details class="ip-help"><summary>Thông tin IP cho biết điều gì?</summary><p>IP công khai là địa chỉ mà dịch vụ bên ngoài nhìn thấy. Khi dùng VPN hoặc proxy, kết quả có thể là IP của cổng kết nối.</p><p>Vị trí theo IP chỉ là ước tính của cơ sở dữ liệu, có thể khác vị trí thực tế. Công cụ không xác nhận bạn có đang dùng VPN hay không.</p><p>Không thể xác định IP LAN hoặc địa chỉ nhà chính xác bằng công cụ này.</p></details>'}
async function lookupIp(value){let inspected;if(value.trim()){inspected=ToolHubLogic.inspectIp(value);if(!inspected.isPublic){const fields=[['Phiên bản',inspected.version],['Phân loại',inspected.scope],['Vị trí / nhà mạng','Không tra cứu cho dải IP này']];return {ip:inspected.ip,fields,note:'Đã phân tích tại trình duyệt. IP này không được gửi đến dịch vụ bên ngoài.',text:ipText(inspected.ip,fields)}}}else if(activeAction===1)throw Error('Nhập địa chỉ IP cần tra cứu hoặc chọn “Xem IP của tôi”.');
  ipRequest?.abort();const controller=new AbortController();ipRequest=controller;const timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('https://api.ip.sb/geoip'+(inspected?'/'+encodeURIComponent(inspected.ip):''),{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store'});if(response.status===429)throw Error('Dịch vụ đã đạt giới hạn tra cứu. Vui lòng thử lại sau.');if(!response.ok)throw Error('Dịch vụ tra cứu tạm thời không phản hồi. Hãy thử lại.');const raw=await response.json();const offset=Number(raw.offset);const utc=Number.isFinite(offset)?(offset<0?'-':'+')+String(Math.floor(Math.abs(offset)/3600)).padStart(2,'0')+':'+String(Math.floor(Math.abs(offset)%3600/60)).padStart(2,'0'):null;const data={...raw,connection:{isp:raw.isp,org:raw.organization||raw.asn_organization,asn:raw.asn},continent:({NA:'Bắc Mỹ',SA:'Nam Mỹ',AS:'Châu Á',EU:'Châu Âu',AF:'Châu Phi',OC:'Châu Đại Dương',AN:'Châu Nam Cực'})[raw.continent_code]||raw.continent_code,timezone:{id:raw.timezone,utc}};if(raw.error||!data.ip)throw Error('Dịch vụ không có thông tin cho IP này. Kiểm tra địa chỉ và thử lại.');const parsed=ToolHubLogic.inspectIp(data.ip);if(inspected&&parsed.ip!==inspected.ip)throw Error('Dịch vụ trả về địa chỉ IP không khớp. Vui lòng thử lại.');const display=v=>v===undefined||v===null||v===''?'Không có dữ liệu':String(v).slice(0,250);const fields=[['Phiên bản',parsed.version],['Nhà mạng (ISP)',display(data.connection?.isp)],['Tổ chức',display(data.connection?.org)],['ASN',data.connection?.asn?'AS'+display(data.connection.asn):'Không có dữ liệu'],['Quốc gia',display(data.country)+(data.country_code?' ('+display(data.country_code)+')':'')],['Tỉnh / khu vực',display(data.region)],['Thành phố ước tính',display(data.city)],['Châu lục',display(data.continent)],['Múi giờ',display(data.timezone?.id)],['Độ lệch UTC',display(data.timezone?.utc)],['Thời điểm tra cứu',new Date().toLocaleString('vi-VN')]];return {ip:parsed.ip,fields,note:'Nguồn: IP.SB · Vị trí theo IP là ước tính, không phải địa chỉ chính xác.',text:ipText(parsed.ip,fields)+'\n\nNguồn: IP.SB. Vị trí chỉ là ước tính.'};}catch(error){if(error.name==='AbortError')throw Error('Tra cứu quá thời gian chờ. Kiểm tra kết nối và thử lại.');if(error instanceof TypeError)throw Error('Không kết nối được dịch vụ IP. Kiểm tra mạng hoặc trình chặn nội dung, rồi thử lại.');throw error}finally{clearTimeout(timer);if(ipRequest===controller)ipRequest=null}}
function ipText(ip,fields){return 'Địa chỉ IP: '+ip+'\n'+fields.map(([label,value])=>label+': '+value).join('\n')}
function renderIpResult(result){lastIpData=result;$('#input').value=result.ip;const container=$('#ipResult');container.replaceChildren();container.hidden=false;const hero=document.createElement('div');hero.className='ip-address';const label=document.createElement('span');label.textContent='ĐỊA CHỈ IP';const address=document.createElement('strong');address.textContent=result.ip;const copy=document.createElement('button');copy.textContent='Sao chép IP';copy.onclick=async()=>{try{await navigator.clipboard.writeText(result.ip);$('#status').textContent='Đã sao chép địa chỉ IP.'}catch{$('#status').textContent='Không sao chép được. Bạn có thể chọn IP trong báo cáo bên dưới.'}};hero.append(label,address,copy);const list=document.createElement('dl');list.className='ip-details';for(const [key,value] of result.fields){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key;dd.textContent=value;row.append(dt,dd);list.append(row)}const note=document.createElement('p');note.className='ip-result-note';note.textContent=result.note;container.append(hero,list,note)}

const signatureKeys=['name','title','company','email','phone','mobile','website','address','linkedin','facebook','instagram','github','twitter','customLabel','custom','logo','accent','color','background','font','size','imageSize','template','disclaimer'];
function signatureFields(){const input=(key,label,value='',type='text')=>field('sig-'+key,label,value,type);return `<div class="signature-layout"><label for="sig-template">Mẫu chữ ký</label><select id="sig-template"><option value="classic">Cổ điển · logo bên trái</option><option value="compact">Gọn gàng · xếp dọc</option><option value="banner">Điểm nhấn · đường màu</option></select><button id="sigJump" disabled>Xem trước chữ ký ↓</button></div><details class="signature-section" open><summary>Thông tin cá nhân</summary>${input('name','Họ và tên *','Nguyễn Minh Anh')}${input('title','Chức danh','Product Designer')}${input('company','Công ty / tổ chức','Studio Mộc')}</details><details class="signature-section" open><summary>Thông tin liên hệ</summary>${input('email','Email','minhanh@example.com','email')}${input('phone','Điện thoại')}${input('mobile','Di động')}${input('website','Website','example.com')}<label for="sig-address">Địa chỉ</label><textarea id="sig-address" rows="2" placeholder="Địa chỉ công ty (tùy chọn)"></textarea></details><details class="signature-section"><summary>Mạng xã hội & liên kết</summary>${input('linkedin','LinkedIn')}${input('facebook','Facebook')}${input('instagram','Instagram')}${input('github','GitHub')}${input('twitter','X / Twitter')}${input('customLabel','Tên liên kết khác')}${input('custom','URL liên kết khác')}</details><details class="signature-section" open><summary>Kiểu chữ & màu sắc</summary><div class="signature-colors">${input('accent','Màu chủ đạo','#236b52','color')}${input('color','Màu chữ','#33443b','color')}${input('background','Màu nền','#ffffff','color')}</div><label for="sig-font">Phông chữ</label><select id="sig-font"><option value="arial">Arial</option><option value="verdana">Verdana</option><option value="georgia">Georgia</option><option value="tahoma">Tahoma</option></select>${input('size','Cỡ chữ (12–18 px)',14,'number')}${input('logo','URL logo / ảnh đại diện (HTTPS)')}${input('imageSize','Chiều rộng ảnh (48–120 px)',80,'number')}<p class="signature-note">Ảnh cần có URL HTTPS công khai. Xem trước và email sẽ tải ảnh từ URL này; một số ứng dụng email có thể chặn ảnh ngoài.</p></details><details class="signature-section"><summary>Ghi chú cuối chữ ký</summary><label for="sig-disclaimer">Ghi chú / thông báo</label><textarea id="sig-disclaimer" rows="3" placeholder="Thông điệp hoặc lưu ý ở cuối chữ ký"></textarea></details><p class="signature-note">Thông tin chữ ký được xử lý trong trình duyệt và giữ trong phiên đang mở. Các trường không nhập sẽ tự ẩn.</p>`}
function readSignature(){const data={};for(const key of signatureKeys)data[key]=$('#sig-'+key).value;return data}
function fillSignatureExample(){const sample={name:'Nguyễn Minh Anh',title:'Product Designer',company:'Studio Mộc',email:'minhanh@example.com',website:'example.com',phone:'+84 28 1234 5678',mobile:'',address:'Thành phố Hồ Chí Minh',linkedin:'https://www.linkedin.com/',facebook:'',instagram:'',github:'',twitter:'',custom:'',customLabel:'',logo:'',accent:'#236b52',color:'#33443b',background:'#ffffff',font:'arial',size:14,imageSize:80,template:'classic',disclaimer:''};for(const key of signatureKeys)$('#sig-'+key).value=sample[key]??''}
function clearSignature(){++resultRevision;clearTimeout(autoTimer);for(const key of signatureKeys){const el=$('#sig-'+key);el.value=({accent:'#236b52',color:'#33443b',background:'#ffffff',font:'arial',size:14,imageSize:80,template:'classic'})[key]??''}lastSignature=null;$('#signatureResult').hidden=true;$('#output').value='';$('#status').textContent='Đã xóa thông tin. Nhập họ tên để tạo chữ ký mới.';$('#status').dataset.error='false';$('#status').style.color='';syncResult();rememberDraft();$('#sig-name').focus()}
function renderSignature(result){lastSignature=result;$('#sigJump').onclick=()=>document.querySelector('.output-pane').scrollIntoView({block:'start'});const container=$('#signatureResult');container.hidden=false;container.replaceChildren();const toolbar=document.createElement('div');toolbar.className='signature-preview-toolbar';const label=document.createElement('strong');label.textContent='Chữ ký của bạn';const button=document.createElement('button');button.id='copySignature';button.textContent='Sao chép chữ ký';button.onclick=()=>copySignature(result);toolbar.append(label,button);const iframe=document.createElement('iframe');iframe.title='Xem trước chữ ký email';iframe.setAttribute('sandbox','');iframe.referrerPolicy='no-referrer';iframe.srcdoc='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src https:; style-src \'unsafe-inline\'; base-uri \'none\'"></head><body style="margin:0;padding:24px;background:#fff;">'+result.html+'</body></html>';const help=document.createElement('div');help.className='signature-install';help.innerHTML='<details><summary>Cách dùng trong Gmail, Outlook hoặc Apple Mail</summary><ol><li>Nhấn <strong>Sao chép chữ ký</strong> để sao chép phần có định dạng.</li><li>Mở cài đặt chữ ký trong ứng dụng email, tạo chữ ký mới rồi dán bằng Ctrl+V hoặc ⌘V.</li><li>Lưu và gửi thử một email để kiểm tra bố cục, liên kết và ảnh.</li></ol><p>Nút “Sao chép HTML” dành cho trình soạn thảo hỗ trợ mã HTML. Cách hiển thị có thể khác giữa các ứng dụng email.</p></details><span class="signature-code-label">Mã HTML · có thể sao chép hoặc tải xuống</span>';container.append(toolbar,iframe,help);$('#sig-size').min=12;$('#sig-size').max=18;$('#sig-imageSize').min=48;$('#sig-imageSize').max=120;$('#fields').querySelectorAll('input[type=text],input[type=email]').forEach(el=>el.maxLength=500)}
async function copySignature(result){try{if(navigator.clipboard?.write&&typeof ClipboardItem!=='undefined'){await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([result.html],{type:'text/html'}),'text/plain':new Blob([result.text],{type:'text/plain'})})]);}else{const scratch=document.createElement('div');scratch.contentEditable='true';scratch.style.cssText='position:fixed;left:-9999px;top:0;background:white;';scratch.innerHTML=result.html;document.body.append(scratch);const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(scratch);selection.removeAllRanges();selection.addRange(range);let copied;try{copied=document.execCommand('copy')}finally{selection.removeAllRanges();scratch.remove()}if(!copied)throw Error('copy unavailable')}$('#status').textContent='Đã sao chép chữ ký có định dạng. Dán vào phần chữ ký của ứng dụng email.';$('#status').style.color='';}catch{$('#status').textContent='Trình duyệt chưa cho phép sao chép định dạng. Tải file HTML, mở file và chọn chữ ký để sao chép thủ công.';$('#status').style.color='#b14e3e'}}

const currencyCache=new Map();let currencyRequest;
function currencyFields(){const options=selected=>Object.entries(ToolHubCurrency.currencies).map(([code,name])=>`<option value="${code}" ${code===selected?'selected':''}>${code} — ${name}</option>`).join('');return '<div class="currency-presets"><span>Cặp thường dùng</span><div><button data-pair="USD,VND">USD → VND</button><button data-pair="EUR,VND">EUR → VND</button><button data-pair="JPY,VND">JPY → VND</button><button data-pair="VND,USD">VND → USD</button></div></div>'+field('fxAmount','Số tiền cần đổi','100')+'<p class="currency-hint">Ví dụ: 1000000 hoặc 1000,50. Không dùng dấu phân cách hàng nghìn.</p><label for="fxFrom">Từ đồng tiền</label><select id="fxFrom">'+options('USD')+'</select><button id="fxSwap" class="currency-swap">⇅ Đảo chiều hai đồng tiền</button><label for="fxTo">Sang đồng tiền</label><select id="fxTo">'+options('VND')+'</select><div class="currency-disclosure"><strong>Tỷ giá tham khảo theo ngày</strong><p>Không phải tỷ giá mua/bán của ngân hàng và chưa gồm phí. Ngày tỷ giá có thể là ngày làm việc gần nhất.</p><p>Chỉ mã đồng tiền được gửi tới Frankfurter để lấy tỷ giá; số tiền được tính trong trình duyệt.</p></div>'}
function setupCurrency(){const input=$('#fxAmount');input.inputMode='decimal';input.maxLength=40;$('#fxSwap').onclick=()=>{const from=$('#fxFrom').value;$('#fxFrom').value=$('#fxTo').value;$('#fxTo').value=from;chooseAction(0);runAction()};$('#fields').querySelectorAll('[data-pair]').forEach(b=>b.onclick=()=>{const [from,to]=b.dataset.pair.split(',');$('#fxFrom').value=from;$('#fxTo').value=to;chooseAction(0);runAction()})}
async function convertCurrency(force){const rawAmount=$('#fxAmount').value,amount=ToolHubCurrency.amount(rawAmount),from=$('#fxFrom').value,to=$('#fxTo').value;if(!Object.hasOwn(ToolHubCurrency.currencies,from)||!Object.hasOwn(ToolHubCurrency.currencies,to))throw Error('Chọn hai đồng tiền trong danh sách.');let data,cached=false;if(from===to)data={base:from,quote:to,rate:1,date:null};else{const priority=['USD','EUR','GBP','CHF','AUD','CAD','SGD','NZD','HKD'];const rank=code=>priority.includes(code)?priority.indexOf(code):100;const [apiFrom,apiTo]=[from,to].sort((a,b)=>rank(a)-rank(b)||a.localeCompare(b));const key=apiFrom+'/'+apiTo,cache=currencyCache.get(key);if(!force&&cache&&Date.now()-cache.loadedAt<600000){data=cache.data;cached=true}else{currencyRequest?.abort();const controller=new AbortController();currencyRequest=controller;const timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('https://api.frankfurter.dev/v2/rate/'+apiFrom+'/'+apiTo,{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store'});if(response.status===429)throw Error('Dịch vụ tỷ giá đang giới hạn yêu cầu. Hãy thử lại sau.');if(!response.ok)throw Error('Chưa lấy được tỷ giá cho cặp tiền này. Vui lòng thử lại.');data=await response.json();if(data.base!==apiFrom||data.quote!==apiTo||!Number.isFinite(data.rate)||data.rate<=0||!/^\d{4}-\d{2}-\d{2}$/.test(data.date)||Number.isNaN(Date.parse(data.date)))throw Error('Nguồn trả về dữ liệu tỷ giá chưa hợp lệ. Hãy cập nhật lại.');currencyCache.set(key,{data,loadedAt:Date.now()});}catch(error){if(error.name==='AbortError')throw Error('Lấy tỷ giá quá thời gian chờ. Kiểm tra mạng và thử lại.');if(error instanceof TypeError)throw Error('Không kết nối được nguồn tỷ giá. Kiểm tra mạng rồi thử lại.');throw error}finally{clearTimeout(timer);if(currencyRequest===controller)currencyRequest=null}}}const effectiveRate=from===data.base?data.rate:1/data.rate;const converted=ToolHubCurrency.convert(rawAmount,effectiveRate);const format=ToolHubCurrency.format;const date=data.date?data.date.split('-').reverse().join('/'):'Không cần tỷ giá (cùng đồng tiền)';const unit=new Intl.NumberFormat('vi-VN',{maximumSignificantDigits:10}).format(effectiveRate),inverse=new Intl.NumberFormat('vi-VN',{maximumSignificantDigits:10}).format(1/effectiveRate);const text=`${format(amount,from)} = ${ToolHubCurrency.formatConverted(converted,to)}\n1 ${from} = ${unit} ${to}\n1 ${to} = ${inverse} ${from}\nNgày tỷ giá: ${date}\n${from===to?'Tỷ lệ 1:1, tính tại trình duyệt.':'Nguồn: Frankfurter — https://frankfurter.dev/'}\nKết quả hiển thị được làm tròn; số nhỏ có thể có thêm chữ số thập phân. Tỷ giá tham khảo, chưa gồm phí.`;return {amount,converted,from,to,rate:effectiveRate,date,rawDate:data.date,cached,text,unit,inverse}}
function renderCurrency(result){lastCurrency=result;const container=$('#currencyResult');container.hidden=false;container.replaceChildren();const hero=document.createElement('div');hero.className='currency-hero';const label=document.createElement('span');label.textContent=ToolHubCurrency.format(result.amount,result.from)+' tương đương';const value=document.createElement('strong');value.textContent=ToolHubCurrency.formatConverted(result.converted,result.to);const pair=document.createElement('p');pair.textContent='1 '+result.from+' = '+result.unit+' '+result.to;hero.append(label,value,pair);const detail=document.createElement('div');detail.className='currency-details';for(const line of ['Chiều ngược: 1 '+result.to+' = '+result.inverse+' '+result.from,'Ngày tỷ giá: '+result.date,result.from===result.to?'Cùng đồng tiền · tính tại trình duyệt':result.cached?'Nguồn: Frankfurter · tỷ giá đã lấy trong 10 phút gần đây':'Nguồn: Frankfurter · vừa lấy từ dịch vụ','Kết quả hiển thị được làm tròn; số nhỏ có thể có thêm chữ số thập phân. Chưa gồm phí.']){const p=document.createElement('p');p.textContent=line;detail.append(p)}container.append(hero,detail)}

function randomFields(){return '<div class="random-bounds">'+field('rngMin','Giá trị nhỏ nhất',1,'number')+field('rngMax','Giá trị lớn nhất',100,'number')+'</div>'+field('rngCount','Số lượng cần tạo (1–1000)',10,'number')+'<label for="rngDecimals">Chữ số thập phân</label><select id="rngDecimals"><option value="0">Số nguyên</option>'+[1,2,3,4,5,6].map(n=>`<option value="${n}">${n} chữ số thập phân</option>`).join('')+'</select>'+checkbox('rngUnique','Không trùng lặp',true)+'<label for="rngSort">Thứ tự kết quả</label><select id="rngSort"><option value="random">Giữ thứ tự ngẫu nhiên</option><option value="asc">Tăng dần</option><option value="desc">Giảm dần</option></select><p class="random-note">Bao gồm cả hai giới hạn. Với số thập phân, bước giữa các giá trị là 10⁻ᵈ theo độ chính xác đã chọn. Ví dụ: 0 đến 1 với 2 chữ số có 101 giá trị.</p><p class="random-note">Tạo bằng bộ sinh ngẫu nhiên mật mã ngay trong trình duyệt. Kết quả không gửi lên máy chủ.</p>'}
function readRandom(){return {min:$('#rngMin').value,max:$('#rngMax').value,count:$('#rngCount').value,decimals:$('#rngDecimals').value,unique:$('#rngUnique').checked,sort:$('#rngSort').value}}
function renderRandom(result){lastRandom=result;const root=$('#randomResult');root.hidden=false;root.replaceChildren();const header=document.createElement('div');header.className='random-summary';header.textContent=`${result.count} số · ${result.min} → ${result.max} · ${result.unique?'Không trùng lặp':'Cho phép lặp'}`;const grid=document.createElement('div');grid.className='random-values'+(result.count===1?' single':'');for(const value of result.values){const span=document.createElement('span');span.textContent=value;grid.append(span)}root.append(header,grid);$('#rngCount').min=1;$('#rngCount').max=1000;$('#rngCount').step=1;for(const id of ['rngMin','rngMax'])$('#'+id).step='any'}
const stopwatch=new ToolHubRandomTime.Stopwatch();let stopwatchFrame=0;
function setupStopwatch(){const root=$('#stopwatchWorkspace');root.innerHTML='<div class="stopwatch-console"><div class="stopwatch-eyebrow">THỜI GIAN ĐÃ TRÔI QUA</div><div id="swTime" role="timer" aria-live="off">00:00:00<span>.00</span></div><div class="stopwatch-units">giờ : phút : giây . phần trăm giây</div><p class="stopwatch-split">Vòng hiện tại: <strong id="swSplit">00:00:00.00</strong></p><div class="stopwatch-controls"><button id="swToggle">Bắt đầu</button><button id="swLap">Ghi vòng</button><button id="swReset">Đặt lại</button></div><p id="swStatus" role="status" aria-live="polite"></p></div><div class="stopwatch-laps"><div class="stopwatch-laps-head"><h3>Các vòng đã ghi <span id="swLapCount">0</span></h3><div><button id="swCopy">Sao chép</button><button id="swExport">Tải CSV</button></div></div><div id="swEmpty">Nhấn “Bắt đầu”, sau đó “Ghi vòng” để lưu thời gian từng vòng.</div><div class="stopwatch-table-wrap"><table id="swTable" hidden><thead><tr><th scope="col">Vòng</th><th scope="col">Thời gian vòng</th><th scope="col">Tổng thời gian</th></tr></thead><tbody id="swRows"></tbody></table></div></div><p class="stopwatch-note">Đồng hồ tiếp tục chạy khi chuyển công cụ hoặc sang tab khác. Tải lại hoặc đóng trang sẽ đặt lại đồng hồ và danh sách vòng.</p>';
$('#swToggle').onclick=()=>{if(stopwatch.running){stopwatch.pause();$('#swStatus').textContent='Đã tạm dừng.'}else{stopwatch.start();$('#swStatus').textContent='Đồng hồ đang chạy.'}refreshStopwatch()};$('#swLap').onclick=()=>{const lap=stopwatch.lap();if(lap){$('#swStatus').textContent='Đã ghi vòng '+lap.index+'.';renderLaps();refreshStopwatch()}};$('#swReset').onclick=()=>{stopwatch.reset();$('#swStatus').textContent='Đã đặt lại đồng hồ và các vòng.';renderLaps();refreshStopwatch()};$('#swCopy').onclick=async()=>{try{await navigator.clipboard.writeText(stopwatchReport());$('#swStatus').textContent='Đã sao chép thời gian và các vòng.'}catch{$('#swStatus').textContent='Chưa sao chép được. Bạn có thể tải CSV để lưu kết quả.'}};$('#swExport').onclick=()=>{const lines=['Vòng,Thời gian vòng,Tổng thời gian',...stopwatch.laps.map(l=>[l.index,ToolHubRandomTime.timeLabel(l.split),ToolHubRandomTime.timeLabel(l.total)].join(','))];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='toolhub-cac-vong-bam-gio.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};renderLaps();refreshStopwatch()}
function stopwatchReport(){return 'Tổng thời gian: '+ToolHubRandomTime.timeLabel(stopwatch.elapsed())+'\nTrạng thái: '+(stopwatch.running?'Đang chạy':'Đã dừng')+'\n'+stopwatch.laps.map(l=>'Vòng '+l.index+': '+ToolHubRandomTime.timeLabel(l.split)+' · Tổng '+ToolHubRandomTime.timeLabel(l.total)).join('\n')}
function renderLaps(){if(!$('#swRows'))return;$('#swRows').replaceChildren();for(const lap of [...stopwatch.laps].reverse()){const row=document.createElement('tr');for(const value of [lap.index,ToolHubRandomTime.timeLabel(lap.split),ToolHubRandomTime.timeLabel(lap.total)]){const cell=document.createElement('td');cell.textContent=value;row.append(cell)}$('#swRows').append(row)}$('#swLapCount').textContent=stopwatch.laps.length;$('#swEmpty').hidden=!!stopwatch.laps.length;$('#swTable').hidden=!stopwatch.laps.length;$('#swExport').disabled=!stopwatch.laps.length;}
function refreshStopwatch(){cancelAnimationFrame(stopwatchFrame);paintStopwatch()}
function paintStopwatch(){if(current?.id!=='stopwatch'||!$('#dialog').open)return;const elapsed=stopwatch.elapsed(),label=ToolHubRandomTime.timeLabel(elapsed),parts=label.split('.');$('#swTime').replaceChildren(document.createTextNode(parts[0]));const centis=document.createElement('span');centis.textContent='.'+parts[1];$('#swTime').append(centis);$('#swSplit').textContent=ToolHubRandomTime.timeLabel(elapsed-(stopwatch.laps.at(-1)?.total||0));$('#swToggle').textContent=stopwatch.running?'Tạm dừng':elapsed?'Tiếp tục':'Bắt đầu';$('#swLap').disabled=!stopwatch.running;$('#swReset').disabled=!elapsed&&!stopwatch.laps.length;$('#swCopy').disabled=!elapsed&&!stopwatch.laps.length;if(stopwatch.running&&!document.hidden)stopwatchFrame=requestAnimationFrame(paintStopwatch)}
document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(stopwatchFrame);if(!document.hidden&&current?.id==='stopwatch'&&$('#dialog').open)paintStopwatch()});

const fakeSchemas={users:{id:'id',uuid:'uuid',name:'fullName',email:'email',age:'integer:18:65',active:'boolean',createdAt:'date'},products:{id:'uuid',name:'pick:Bàn phím|Chuột|Màn hình|Tai nghe',company:'company',price:'number:10:1000:2',stock:'integer:0:100',category:'pick:Điện tử|Phụ kiện'},orders:{id:'uuid',customer:'fullName',email:'email',total:'number:100:5000:2',status:'pick:pending|paid|shipped',createdAt:'date'}};
function devFields(id){const input=(key,label,value='',type='text')=>field(key,label,value,type);if(id==='fakejson')return '<label for="fakePreset">Mẫu schema</label><select id="fakePreset"><option value="users">Người dùng</option><option value="products">Sản phẩm</option><option value="orders">Đơn hàng</option></select>'+input('fakeCount','Số bản ghi (1–1000)',10,'number')+'<label for="fakeSchema">Schema JSON · tên trường: loại dữ liệu</label><textarea id="fakeSchema">'+JSON.stringify(fakeSchemas.users,null,2)+'</textarea><details class="dev-help"><summary>Các loại dữ liệu được hỗ trợ</summary><p>id, uuid, fullName, email, company, country, boolean, date</p><p>integer:18:65 · number:10:100:2 · pick:A|B|C · literal:Nội dung cố định</p><p>Schema phẳng tối đa 30 trường. id và email được đánh số trong từng lần tạo; các giá trị khác có thể lặp. Dữ liệu ngày nằm trong khoảng thử nghiệm 2024–2026.</p></details>';
if(id==='jwt')return textInput+input('jwtSecret','Khóa bí mật UTF-8 (chỉ cần khi xác minh HMAC)','','password')+'<div class="dev-notice">Giải mã không đồng nghĩa token hợp lệ. Hỗ trợ xác minh HS256 / HS384 / HS512; chưa kiểm tra issuer, audience hoặc thu hồi token. Token và khóa không được gửi đi. Khóa không được giữ khi chuyển công cụ.</div>';
if(id==='hash')return textInput+'<label for="hashAlgorithm">Thuật toán</label><select id="hashAlgorithm"><option>SHA-256</option><option>SHA-384</option><option>SHA-512</option><option>SHA-1</option><option>MD5</option></select><label for="hashEncoding">Định dạng kết quả</label><select id="hashEncoding"><option value="hex">Hex</option><option value="base64">Base64</option></select>'+checkbox('hashHmac','Chế độ HMAC (có khóa)',false)+input('hashSecret','Khóa HMAC UTF-8','','password')+input('hashExpected','Giá trị đối chiếu (tùy chọn)')+'<p class="dev-note">Nội dung được băm nguyên vẹn theo UTF-8, gồm khoảng trắng và xuống dòng. MD5 / SHA-1 dành cho tương thích; không phải công cụ lưu mật khẩu an toàn. Khóa không được giữ khi chuyển công cụ.</p>';
if(id==='meta')return input('meta-title','Tiêu đề trang *','ToolHub — Công cụ làm việc mỗi ngày')+'<label for="meta-description">Mô tả trang</label><textarea id="meta-description">Các công cụ hữu ích cho lập trình viên và công việc hằng ngày.</textarea>'+input('meta-url','URL chuẩn (canonical)','https://example.com/')+input('meta-image','URL ảnh chia sẻ (HTTP/HTTPS)')+input('meta-site','Tên website','ToolHub')+input('meta-author','Tác giả')+'<label for="meta-robots">Cho phép lập chỉ mục</label><select id="meta-robots"><option value="index">index, follow</option><option value="noindex">noindex, nofollow</option></select>'+checkbox('meta-og','Tạo Open Graph',true)+checkbox('meta-twitter','Tạo Twitter Card',true)+'<label for="meta-type">Loại nội dung</label><select id="meta-type"><option value="website">Website</option><option value="article">Article</option></select>'+input('meta-locale','Ngôn ngữ Open Graph','vi_VN')+input('meta-twitterSite','Tài khoản X / Twitter (tùy chọn)','','text')+'<p class="dev-note">Chỉ sinh mã HTML, không tải nội dung hoặc ảnh từ URL. Chèn kết quả vào phần &lt;head&gt; của trang.</p>';
if(id==='campaign')return input('utm-url','URL trang đích *','https://example.com/?ref=toolhub#intro')+input('utm-source','Nguồn chiến dịch · utm_source *','newsletter')+input('utm-medium','Phương tiện · utm_medium *','email')+input('utm-campaign','Tên chiến dịch · utm_campaign *','ra-mat-san-pham')+input('utm-term','Từ khóa · utm_term')+input('utm-content','Nội dung / biến thể · utm_content')+input('utm-id','Mã chiến dịch · utm_id')+'<p class="dev-note">Tham số phân biệt chữ hoa/thường. Giữ cách đặt tên nhất quán. UTM đã có được thay thế; các UTM tùy chọn để trống sẽ được bỏ. Công cụ chỉ tạo URL, không mở hoặc gửi truy cập đến URL đó.</p>';return textInput}
function readHash(){return {text:val(),algorithm:$('#hashAlgorithm').value,encoding:$('#hashEncoding').value,hmac:$('#hashHmac').checked,key:$('#hashSecret').value,expected:$('#hashExpected').value}}
function readMeta(){const data={};for(const key of ['title','description','url','image','site','author','robots','type','locale','twitterSite'])data[key]=$('#meta-'+key).value;data.og=$('#meta-og').checked;data.twitter=$('#meta-twitter').checked;return data}
function readCampaign(){const data={};for(const key of ['url','source','medium','campaign','term','content','id'])data[key]=$('#utm-'+key).value;return data}
function setupDev(id){for(const key of ['jwtSecret','hashSecret'])if($('#'+key)){$('#'+key).autocomplete='off';$('#'+key).spellcheck=false;}$('#fields').querySelectorAll('input[type=text],input[type=password]').forEach(el=>el.maxLength=10000);if(id==='fakejson'){$('#fakeCount').min=1;$('#fakeCount').max=1000;$('#fakePreset').onchange=()=>{$('#fakeSchema').value=JSON.stringify(fakeSchemas[$('#fakePreset').value],null,2);chooseAction(0);runAction()}}if(id==='hash'){$('#hashSecret').disabled=!$('#hashHmac').checked;$('#hashHmac').addEventListener('change',()=>$('#hashSecret').disabled=!$('#hashHmac').checked)}}
function renderDev(result){lastDev=result;const container=$('#devResult');container.hidden=false;container.replaceChildren();for(const line of result.summary||[]){const p=document.createElement('p');p.textContent=line;if(/KHÔNG|hết hạn|Chưa xác minh/.test(line))p.className='dev-warning';container.append(p)}}
async function fillDevExample(id){if(id==='hash'){$('#input').value='Xin chào Việt Nam!';$('#hashAlgorithm').value='SHA-256';$('#hashEncoding').value='hex';$('#hashHmac').checked=false;$('#hashSecret').value='';$('#hashSecret').disabled=true;$('#hashExpected').value=''}if(id==='jwt'){const encode=s=>btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(s)))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');const body=encode({alg:'HS256',typ:'JWT'})+'.'+encode({iss:'toolhub-example',sub:'demo-user',name:'Nguyễn Demo',iat:1700000000,exp:1893456000});const key=await crypto.subtle.importKey('raw',new TextEncoder().encode('demo-secret'),{name:'HMAC',hash:'SHA-256'},false,['sign']);const signature=btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode(body))))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');if(current.id!=='jwt')return;$('#input').value=body+'.'+signature;$('#jwtSecret').value='demo-secret'}if(id==='meta'){for(const [key,value] of Object.entries({title:'ToolHub — Công cụ mỗi ngày',description:'Bộ công cụ tiện ích cho công việc.',url:'https://example.com/',image:'',site:'ToolHub',author:'',robots:'index',type:'website',locale:'vi_VN',twitterSite:''}))$('#meta-'+key).value=value;$('#meta-og').checked=true;$('#meta-twitter').checked=true}if(id==='campaign'){for(const [key,value] of Object.entries({url:'https://example.com/products?ref=toolhub#intro',source:'facebook',medium:'social',campaign:'ra-mat-san-pham',term:'',content:'banner-a',id:''}))$('#utm-'+key).value=value}}
